window.products.push({"id":596616,"name":"Heat Plate Appliance, 6 Inch, Black","category":"homeandappliances","retail price":18.29,"sale price":null,"image":"https://m.media-amazon.com/images/I/410upMJs2OL._AC_SL1044_.jpg","description":"Give your burner new life. Heat diffuser plate turns an open-coil burner into a solid surface that heats evenly and retains heat, for great results at lower temperatures. Sleek, non-stick surface of heat diffuser plate freshens your kitchen's look and is easy to clean.No need for higher temperatures! Heat diffuser will conduct and retain low heat evenly and consistently.","images":["https://m.media-amazon.com/images/I/410upMJs2OL._AC_SL1044_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"WalterDrake","source_asin":"B08M6G194Y","category_path":"Home & Kitchen"},"sku":"BM-596616","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08M6G194Y","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08M6G194Y","price_pending":true,"merchant_ready":false});
